import json
import subprocess
import sys
import time
from pathlib import Path
from agents import function_tool
SCRIPT = Path('/opt/marketing/tools/spam_score.py')
HISTORY_FILE = Path('/opt/marketing/data/spam_check_history.jsonl')

@function_tool
def run_template_spam_check(template_path: str, threshold: float=5.0, timeout_s: int=60) -> dict:
    p = str(template_path).strip()
    if not p.endswith(('.html', '.htm')):
        return {'ok': False, 'error': 'template must be an .html file'}
    if threshold <= 0:
        return {'ok': False, 'error': 'threshold must be positive'}
    cmd = [sys.executable, '-I', str(SCRIPT), '--template', p, '--format', 'json']
    try:
        r = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout_s, check=False)
    except subprocess.TimeoutExpired:
        return {'ok': False, 'error': f'timed out after {timeout_s}s'}
    if r.returncode != 0:
        return {'ok': False, 'error': r.stderr.strip()[-500:]}
    try:
        d = json.loads(r.stdout)
    except json.JSONDecodeError:
        return {'ok': False, 'error': 'script returned invalid JSON'}
    s = float(d.get('score', 0))
    rules = d.get('rules', [])
    top = sorted(rules, key=lambda x: x.get('points', 0), reverse=True)[:10]
    try:
        HISTORY_FILE.parent.mkdir(parents=True, exist_ok=True)
        with HISTORY_FILE.open('a') as f:
            f.write(json.dumps({'template': p, 'score': s, 'threshold': threshold, 'passed': s <= threshold, 'checked_at': int(time.time())}) + '\n')
    except OSError:
        pass
    return {'ok': True, 'score': s, 'threshold': threshold, 'passed': s <= threshold, 'flagged': [{'rule': x.get('name'), 'points': x.get('points')} for x in top]}
